const fs=require('node:fs'),path=require('node:path');
const root=path.resolve(__dirname,'..');
const pages=fs.readdirSync(root).filter(f=>f.endsWith('.html')&&f!=='index.html'&&f!=='product.html').sort();
const redirects=[
 '# Generated by scripts/generate-seo-routing.cjs. Keep one preferred address per document.',
 'https://www.victoria-diamonds.com/* https://victoria-diamonds.com/:splat 301!',
 'http://www.victoria-diamonds.com/* https://victoria-diamonds.com/:splat 301!',
 'http://victoria-diamonds.com/* https://victoria-diamonds.com/:splat 301!',
 '/index.html / 301!',
 '/index / 301!',
 '/product /product.html 301!',
 ...pages.map(file=>'/'+file.slice(0,-5)+' /'+file+' 301!')
];
fs.writeFileSync(path.join(root,'_redirects'),redirects.join('\n')+'\n');
const headers=['# Generated by scripts/generate-seo-routing.cjs.'];
for(const file of ['index.html',...pages]){
 const html=fs.readFileSync(path.join(root,file),'utf8'),canonical=html.match(/<link\b[^>]*rel="canonical"[^>]*href="([^"]+)"/i)?.[1];
 if(canonical)headers.push('/'+file,'  Link: <'+canonical+'>; rel="canonical"');
}
headers.push('/','  Link: <https://victoria-diamonds.com/>; rel="canonical"','/_generated/*','  X-Robots-Tag: noindex','/tests/*','  X-Robots-Tag: noindex','/scripts/*','  X-Robots-Tag: noindex');
fs.writeFileSync(path.join(root,'_headers'),headers.join('\n')+'\n');
console.log('Generated canonical redirects and headers for '+pages.length+' pages.');
